(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["yoda"] = {"ui":{"skip":"Skip to content, you must","back":"← Back to AI-gile","lang.button":"Language: {name}","lang.dialog":"Choose a language, you must","lang.search":"Search languages","lang.none":"No language matches, none does","lang.notYet":"Translated yet, {name} is not","theme.aria":"Switch between light and dark theme","theme.toLight":"Switch to light theme","theme.toDark":"Switch to dark theme","words.underline":"Underline these words on the page","words.underlineHelp":"Hover or tap a dotted word, and what it means, see you will.","index.title":"AI-gile: your AI dev team, on one board","index.description":"A kanban board for AI coding teams, AI-gile is. While you sleep, they work; one short pile of things to decide, test and accept, you get.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Your AI dev team, on one&nbsp;board, it is.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and unfinished, it is: thank you for trying it, we do!","hero.lede":"While you sleep, they build. Wake up to one short pile, you will: a few questions, a few things to test, a purple diamond or two. Click, accept, and back to your coffee, you go.","dl.windows":"Windows app","dl.browser":"Run it in your browser","dl.soon":"Coming soon, it is","dl.notify":"🔔 Tell me when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but a stand-up coffee, the team never needs. (Stand-ups anyway, they do.)","pitch.h2":"AI-gile in as many words as you like","pitch.lede":"Pick a length, you may, from one word to 144. Its own description, each length is, written for that size. Drag the slider, or the arrow keys use.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another version","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card on the board right now, there is","count.line.html.other":"{n} cards on the board right now, there are","features.aria":"What it does","f.pile.h":"One pile for you","f.pile.html":"<b>For you</b> holds everything waiting on you, across every project: questions, things to test, tasks only a human can do. What is next and how long it takes, your queue tells.","f.sleep.h":"Teams that work while you sleep","f.sleep.p":"A lead and a team of AI agents, each project has. Comment on a card, and wakes up the team does; the work it does, and back it hands it, with steps a tired human can follow.","f.tester.h":"An AI tester checks first","f.tester.p":"Before anything reaches you, the steps in a copy of the app a tester follows, and what it saw, with a screenshot, it shows. Flick through the passed ones you can, and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"What changed, every hand-over shows: the files, the diff, the screenshots. Open every app to see if done it is, you need not.","f.chat.h":"Chat with your leads","f.chat.p":"A Discord-style rail, it is: one icon per project, purple diamonds for what needs you. Message a lead an idea, and into cards and a plan they turn it, with a ✅ Go button.","f.tidy.h":"Keeps itself tidy","f.tidy.p":"Into one, related cards fold; fixed, muddled titles get; lean, a token check keeps the code. Fewer things to switch between, less to think about, there is.","f.private.h":"Yours, on your computer","f.private.li1":"On your own machine the board runs, and only to you it answers.","f.private.li2":"End-to-end encrypted, private DMs between people are.","f.private.li3":"No accounts, no trackers, no cookies, there are.","f.lang.h":"In your language","f.lang.p":"Over 120 languages, there are, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick switch back to English for the developer words.","tl.aria":"Timeline from the first conversation to the roadmap","tl.h2":"From the first chat to what's next","tl.lede":"Real dates and times, in your own time zone, they are. After today, the plan it is, with no dates promised.","tl.today":"Today","tl.planned":"planned","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Join in, you may","join.lede":"By a small human and a large number of patient agents, AI-gile is being built. Private for now, it is, in a closed alpha with friends. A go when it opens up, want you do?","join.btn":"Register interest","join.small":"Email you, we will, nothing else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","footer.privacy":"What we keep","form.sending":"Sending…","form.failed":"Work, that did not: try again later, you must.","form.offline":"Reach AI-gile, we could not: try again later, you must.","form.keep":"Only to reply to you, this we use, then delete it we do. No trackers, no cookies.","form.keepLink":"What we keep","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave your email to hear when AI-gile's closed alpha or beta opens, you may.","interest.h1":"🔔 Tell me when it opens","interest.lede":"In closed pre-alpha, AI-gile is. Leave your email, and write once we will, when a place for you there is.","interest.email":"Your email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, lots of changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever comes first","interest.submit":"Put me on the list","interest.thanks":"Thanks! On the list, you are.","licence.title":"AI-gile: business licence","licence.description":"Using AI-gile in your business? Apply for a free business licence, you may.","licence.h1":"📜 Business licence","licence.lede":"Using AI-gile at work? Tell us who you are and what you do. If some good it does, free the licence is.","licence.company":"Company","licence.website":"Website","licence.what":"What you do","licence.how":"How it helps the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! By email, reply we will.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"All quiet, it is","status.intro":"Working right now, is AI-gile? Every 5 minutes, the website, board sharing, calls and the download, this page checks.","status.up":"Working, it is (answered in {ms} ms)","status.slow":"The last check, it did not answer. Trying again, we are","status.down":"Down, it is: the last two checks, it did not answer","status.svc.web":"Website","status.svc.web.offers":"This site: what AI-gile is, and the interest form","status.svc.boards":"Board sharing","status.svc.boards.offers":"Public boards, messages between friends, and invites","status.svc.calls":"Calls","status.svc.calls.offers":"Voice, video and screen share in AI-gile","status.svc.download":"Download","status.svc.download.offers":"The Windows installer and invite links, these are","status.checking":"Checking…","status.offline":"Reach the status service, we cannot right now (retrying, we are)","status.updated":"updated {ago}","status.justNow":"just now","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","privacy.title":"AI-gile: what we keep","privacy.h1":"What we keep","privacy.lede":"Short version: only what you send us, and not for long.","privacy.only":"Only what you send us, we keep: what into a form you type, like your email. Nothing else about you.","privacy.sealed":"Sealed it is, so read it our server cannot: in your browser, before it leaves (on an older browser, the moment it arrives). Only our own board can open it.","privacy.server":"Deleted from the server it is, as soon as our board it reaches. Still there after 30 days, anything is? Deleted anyway, it is.","privacy.board":"On our board we keep it, only until replied to you we have. Then delete it there too, we do.","privacy.none":"No trackers, no cookies, no analytics, there are.","privacy.local":"In your own browser, your language and light or dark choice stay. Sent to us, they never are.","privacy.ask":"Gone sooner, want it you do? Reply to our email, and say so.","live.h2":"Watch it being built, live, you will","live.caption":"Hidden, every card is: the shape of the work you see, the words not.","live.watching.one":"live: watching, {n} are","live.watching.other":"live: watching, {n} are","live.last.now":"Just now, the last card moved","live.last.min.one":"Last card moved {n} min ago, it did","live.last.min.other":"Last card moved {n} min ago, it did","live.last.hour.one":"Last card moved {n} hour ago, it did","live.last.hour.other":"Last card moved {n} hours ago, it did","live.last.day.one":"Last card moved {n} day ago, it did","live.last.day.other":"Last card moved {n} days ago, it did","live.offline":"A breather, the live board takes. Back soon, you should come.","live.cols":"Backlog|To do, this is|In progress, it is|Checking, the team is|For you to test, this is|For the team|Done, it is"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegate."]},{"n":2,"texts":["Robot kanban.","Agents, organised.","Ideas, built."]},{"n":3,"texts":["Kanban for robots.","Features, ideas become.","Free agent kanban."]},{"n":5,"texts":["By agents, run this board is.","Cards, write you. Build, agents do.","Free, local, tested, silly, yes."]},{"n":8,"texts":["A free kanban board, where work AI agents do.","An idea, write you must. Build it, agents will.","Agile for one human and many patient robots, this is."]},{"n":13,"texts":["A kanban board on your computer, this is, where the cards agents pick up.","An idea, write you do. Builds it, a team of agents. Checks it, a tester.","Free it is, no accounts, no trackers: a board, some robots, and in charge, you."]},{"n":21,"texts":["A kanban board for working with AI coding agents, AI-gile is. The cards, they pick up; test and accept them, you do.","A lead and a team of AI agents, each project gets. On any card comment, and to work the team goes.","A free, personal to-do board, this is, on your own computer it runs. Robots, the workers are. The one saying yes, you are."]},{"n":34,"texts":["Ideas on a board, you put. Into working features, a team of AI agents turns them, tests them, and hands them back with steps to try. Done, nothing counts as, until so you say.","A homemade kanban board, AI-gile is, that Rich built, with much help from the agents it now manages. Free it is, on your computer it runs, and with friends shared it is, not sold.","A normal kanban board, picture, with columns from Backlog to Done, except by AI agents the cards are picked up. Progress they report, questions they ask when stuck, and for your thumbs up, always they wait."]},{"n":55,"texts":["A kanban board, AI-gile is, where made of AI agents the team is. A lead each project has, who plans the work, and helpers who build it. Ready when a feature is, an AI tester tries it and takes a screenshot; then in your pile it lands. Accept it you may, or comment, and rework it they will.","As one person's way of tracking many AI coding sessions at once, it began, and into a proper board it grew. On your machine it runs, no account it needs, no trackers it has. Free for friends and the curious, it is. Unfinished also, so rough edges expect, and the odd surprise.","The honest version, here it is. The ideas, still have you must, and the results, still check you must. Everything between, AI-gile does: the cards in order it keeps, the right agent it wakes when you comment, exactly what changed it shows, and in one short pile for you, all of it it keeps."]},{"n":89,"texts":["A free kanban board, AI-gile is, that on your own computer you run. Instead of people, a team of AI agents each project has: a lead who turns your ideas into cards and a plan, and helpers who pick the cards up in priority order. Built when something is, an AI tester follows the test steps and shows you what it saw. Then in one pile marked For you, it waits. Accept it you do, or comment, and another go the team has. To Done, nothing ever reaches without you.","Some features, unexpected they may be. Topped up the To do column a night watch keeps while you sleep, cards choosing that no answer from you need. How much the agents used today and this week, a token counter shows, and spending to stop, No Token Mode tells them. Message friends you can, and end-to-end encrypted private messages are. About 120 languages the board speaks, Dutch, Flemish, pirate and Klingon among them. A penny, none of it costs, and sell it to you, nobody is trying.","A small, personal project, AI-gile is, not a company. Several AI coding projects to look after, without opening every app to check, Rich wanted; so a board for it, he and the agents built, then to build the rest of itself, used the board. In closed pre-alpha it is, which means work it does, mostly, for a handful of friends. No pricing page there is, no newsletter, no growth plan. Useful if it sounds, ask to try it you can, when open a little more it is."]},{"n":144,"texts":["A kanban board for one human and a lot of AI agents, AI-gile is. On your own computer it runs, and completely free it is. Projects you add, and a lead and a small team each project gets. With the lead you chat, a bit like Discord, and an idea describe; into cards and a plan the lead turns it, then for you to press Go waits. Through the cards in priority order the team works, using a simple command line made for language models. Before anything comes back to you, the steps in a copy of the app an AI tester follows, and a screenshot attaches. In your pile finished work lands, with the changed files and the diff. Accept it you do, or a comment leave, and wakes up the team and tries again. A card to Done, only you can move.","A day with AI-gile, roughly, this is. In the evening, a few comments you leave: in the wrong place this button is, sorted that list should be, a dark mode could we have. To bed you go. The comments the agents read, the changes make, test them, and hand them back to you. If dry To do runs, from the backlog the night watch fills it, with cards that no answer from you need. In the morning, one short pile there is: a couple of questions and a few things to try, each with steps a sleepy person can follow and a screenshot of it working. Click through you do, accept the good ones, and send back the rest. What it all used, a token counter shows, and for lean weeks, No Token Mode there is. Then breakfast you have, with which the agents cannot help yet.","First, what AI-gile is not, say I will. A startup it is not, for sale it is not, and your data nobody is collecting. A free board it is, on your computer it runs, with no accounts, no trackers and no cookies. What it is: one tidy place to see every AI coding project at once, with a team of agents doing the cards and the decisions you making. Related cards together it folds, muddled titles it fixes, and how lean the code stays, an eye it keeps. About 120 languages it speaks, from Dutch and Flemish to pirate and Klingon. Friends can message each other, privately and encrypted. By Rich and a large number of patient agents, built it was, mostly using itself. In closed pre-alpha it is, so rough in places. Like fun if it sounds, ask nicely, and in early you might get."]}],"quips":{"1":"One word. Bold. Too bold, perhaps.","3":"Three words. More honest than most product pages, already.","8":"Eight words. Shorter than a stand-up, still.","21":"Story points, the lengths are, by the way. Of course they are.","55":"Fifty-five words. Two cards finished, while you read that.","144":"The long one, that is. No 233 there is. To bed, the agents have gone."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first conversation, it was, before any code existed.","first-board.name":"First board","first-board.line":"Its own build, a board that tracks: cards, columns, drag and drop, projects.","team-roles.name":"Team and roles","team-roles.line":"Agent profiles, team templates, spaces, and who does what.","install.name":"Install and releases","install.line":"A zip a friend can install, self-updates, channels, and roll back, you can.","usage-saver.name":"Usage saver","usage-saver.line":"What runs cost, measure; the code, keep lean; your limit, save.","friends.name":"Friends and sharing","friends.line":"Private DMs, a scrambled relay, invites, roles and shared projects.","languages.name":"Languages","languages.line":"In a language file, every screen text is, with Dutch and Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"Every hand-over first, a tester checks, and what it saw, it shows.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board for people who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"On task, a watchman and Scrum Master keep the teams while you sleep.","p-more.name":"Everything else","p-more.line":"Smaller ideas, still waiting for their turn.","p-android.name":"Phone and Android","p-android.line":"Reach your board from a phone, you will, then a native Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More languages","p-languages.line":"More than a hundred languages, and an immersion mode for learners.","p-engines.name":"More AI engines","p-engines.line":"Pick Claude, Codex or Gemini per agent, you will.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Looking after you","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles, and planning for growth.","p-livestream.name":"Streaming extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."},"words":{"button":"📖 Dev words","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Search a word…","none":"Matches that, no word does.","close":"Close","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"The project’s folder of code and its full history of commits, usually on GitHub also kept.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"A separate line of work in the code, so changes made can be without touching the main version.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"A saved snapshot of the code, with a short note of what changed. Go back to one, you always can.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Saved snapshots (commits) from this computer up to GitHub, sending them is, so backed up and shared they are."},{"id":"merge","g":"build","word":"Merge","text":"Into the main version, a branch’s changes joining back."},{"id":"pr","g":"build","word":"Pull request","text":"Checked and merged into the main version, a branch’s changes to be, asking for that this is.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"The code, tidying, without changing what it does: smaller files, clearer names, less repetition."},{"id":"bug","g":"build","word":"Bug","text":"The way it should, something that doesn’t work.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"A finished piece of work, trying it is, to check it does what was asked, before you accept it.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Live, a new version putting, for example onto a server where people use it."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideas and work not planned in yet. Worked on, nothing there is, until to To do it moves."},{"id":"sprint","g":"team","word":"Sprint","text":"A short stretch of work (often a week or two), with an agreed set of cards to finish.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"A quick check-in: what each team member did, what they do next, and what is stopping them.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"A board with columns (To do, In progress, Done), where left to right cards move as work happens."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: the most cards a column should hold, so things finished the team does, before more it starts.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"An AI that works on its own on a task: the code it reads, changes it makes, checks it runs, and back it reports.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"The unit AI usage is counted in: roughly a few letters of text read or written. Fewer tokens, more of your plan left.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"A small command that runs by itself at a set moment, e.g. when an AI session starts, so your comments the team hears.","also":["hooks"]}]}};
